function pickName(first, last) {
  return first || last || 'unknown';
}

console.log(pickName(0, 'Smith'));

output:
**Issue:** JavaScript || treats 0, '' and false as falsy.
**Why:** A legitimately falsy first value is silently discarded, so the wrong branch runs.
**Fix:**
function pickName(first, last) {
  return first ?? last ?? 'unknown';
}

